<template><div class="login"><div class="card"><div class="mark">🍏</div><h1>鲜果铺</h1><p>管理后台</p><el-form @submit.prevent="submit"><el-form-item><el-input v-model="form.username" size="large" placeholder="管理员账号"/></el-form-item><el-form-item><el-input v-model="form.password" size="large" type="password" show-password placeholder="密码" @keyup.enter="submit"/></el-form-item><el-button class="btn" type="primary" size="large" :loading="loading" @click="submit">登录后台</el-button></el-form><small>默认：admin / FreshFruit@2026</small></div></div></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{api}from'../api';const router=useRouter(),loading=ref(false),form=reactive({username:'admin',password:'FreshFruit@2026'});async function submit(){loading.value=true;try{const d:any=await api.post('/auth/admin/login',form);localStorage.setItem('admin_token',d.token);router.push('/dashboard')}catch(e:any){ElMessage.error(e.response?.data?.message||'登录失败')}finally{loading.value=false}}</script>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;background:radial-gradient(circle at 30% 20%,#e4f1e8,transparent 35%),#f6f7f3}.card{width:390px;background:#fff;border-radius:22px;padding:38px 42px;box-shadow:0 20px 60px rgba(25,62,44,.1);text-align:center}.mark{width:66px;height:66px;border-radius:18px;background:#e9f4ed;margin:0 auto 16px;display:grid;place-items:center;font-size:38px}.card h1{margin:0;font-size:28px}.card p{color:#929a94;margin:6px 0 28px}.btn{width:100%;background:#167a4a;border-color:#167a4a}.card small{display:block;color:#b0b5b1;margin-top:20px}</style>
